/* ============ 可插拔存储层：服务端 / 飞书代理 / Supabase / Claude预览 / 本机 ============ */
// 调用飞书代理：统一 POST {op,...}
async function fx(op, payload){
  const r = await fetch(B.proxyUrl, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({op, ...(payload||{})})});
  if(!r.ok) throw 0; return await r.json();
}
// 可读台账（飞书模式）：每条打卡镜像成一行；未配置台账表则代理自动跳过。best-effort，不阻塞主流程
function feishuLogRow(item){
  if(BACKEND_MODE!=='feishu') return;
  const fields={ '记录ID':item.id, '姓名':item.name, '头像':item.avatar||'', '动作类型':item.type,
    '结果':item.result||'', '资源状态':item.status||'', '下一步':item.next||'', '日期':item.date, '打卡时间':item.ts };
  fx('logRow',{fields}).catch(()=>{});
}
function feishuDelRow(id){
  if(BACKEND_MODE!=='feishu') return;
  fx('delRow',{id}).catch(()=>{});
}

/* 个人身份（仅本设备：记住“我是谁”） */
const PERSONAL = {
  async get(k){ try{
      if(CLAUDE){ const r=await window.storage.get(k,false); return r?JSON.parse(r.value):null; }
      const v=localStorage.getItem('bb_'+k); return v?JSON.parse(v):null;
    }catch(e){ return null; } },
  async set(k,v){ try{
      if(CLAUDE){ return await window.storage.set(k,JSON.stringify(v),false); }
      localStorage.setItem('bb_'+k,JSON.stringify(v)); return true;
    }catch(e){ return null; } },
  async del(k){ try{
      if(CLAUDE){ return await window.storage.delete(k,false); }
      localStorage.removeItem('bb_'+k); return true;
    }catch(e){ return null; } }
};

/* 共享数据（全员同步）。值以对象/数组存取。
   server 模式：优先写服务端 JSON 文件；写入失败自动降级 localStorage 兜底 */
const LS_PREFIX = 'bb_shared_';
const LS_FALLBACK_PREFIX = 'bb_fallback_';  // 服务端失败时的本地缓存 key

/* 服务端探活 */
let serverOnline = false;
async function checkServerHealth(){
  if(BACKEND_MODE!=='server') return;
  try{
    const r = await fetch(`${SERVER_URL}/api/health`, {cache:'no-store'});
    serverOnline = r.ok;
  }catch(e){
    serverOnline = false;
  }
  updateConnBar();
}
async function syncFallbackData(){
  if(!serverOnline || BACKEND_MODE!=='server') return;
  // 扫描本地兜底数据，推送到服务端
  for(let i=0; i<localStorage.length; i++){
    const k = localStorage.key(i);
    if(k && k.startsWith(LS_FALLBACK_PREFIX)){
      const realKey = k.slice(LS_FALLBACK_PREFIX.length);
      try{
        const v = JSON.parse(localStorage.getItem(k));
        await fetch(`${SERVER_URL}/api/data`, {
          method:'POST', headers:{'Content-Type':'application/json'},
          body: JSON.stringify({key:realKey, value:v})
        });
        localStorage.removeItem(k);  // 同步成功后清除本地备份
      }catch(e){ /* 同步失败保留本地，下次重试 */ }
    }
  }
}

const SHARED = {
  async get(k){ try{
      if(BACKEND_MODE==='server'){
        // 优先从服务端读
        try{
          const r = await fetch(`${SERVER_URL}/api/data?key=${encodeURIComponent(k)}`);
          if(r.ok){ const d = await r.json(); return d.value !== undefined ? d.value : null; }
        }catch(e){}
        // 服务端不可用：尝试读本地兜底
        const fb = localStorage.getItem(LS_FALLBACK_PREFIX + k);
        if(fb) return JSON.parse(fb);
        // 都没有则尝试读已同步的本地 key
        const v = localStorage.getItem(LS_PREFIX + k);
        return v ? JSON.parse(v) : null;
      }
      if(BACKEND_MODE==='feishu'){ const d=await fx('get',{key:k}); return d.value? JSON.parse(d.value): null; }
      if(BACKEND_MODE==='rest'){
        const r=await fetch(`${B.url}/rest/v1/board_kv?key=eq.${encodeURIComponent(k)}&select=value`,{headers:restHeaders});
        if(!r.ok) throw 0; const a=await r.json(); return a[0]?a[0].value:null;
      }
      if(BACKEND_MODE==='claude'){ const r=await window.storage.get(k,true); return r?JSON.parse(r.value):null; }
      // local: localStorage 持久化，不再用内存
      const v = localStorage.getItem(LS_PREFIX + k);
      return v ? JSON.parse(v) : null;
    }catch(e){ return null; } },
  async set(k,v){ try{
      if(BACKEND_MODE==='server'){
        // 始终先存本地兜底
        localStorage.setItem(LS_FALLBACK_PREFIX + k, JSON.stringify(v));
        // 尝试写服务端
        try{
          const r = await fetch(`${SERVER_URL}/api/data`, {
            method:'POST', headers:{'Content-Type':'application/json'},
            body: JSON.stringify({key:k, value:v})
          });
          const d = await r.json();
          if(d && d.ok){
            localStorage.removeItem(LS_FALLBACK_PREFIX + k);  // 成功则清除兜底
            return true;
          }
          // 服务端返回明确的错误（如 409 重复打卡）→ 抛出异常让调用方处理
          if(d && d.dup){
            throw d;  // 包含 {dup:true, error:"..."}
          }
        }catch(e){
          // 已经是 JS Error 或 dup 对象，向上传播
          if(e && e.dup) throw e;
        }
        // 服务端失败：保留本地兜底，标记状态
        updateConnBar();
        return true;  // 本地已存，不报失败
      }
      if(BACKEND_MODE==='feishu'){ const d=await fx('set',{key:k, value:JSON.stringify(v)}); return d&&d.ok; }
      if(BACKEND_MODE==='rest'){
        const r=await fetch(`${B.url}/rest/v1/board_kv`,{method:'POST',
          headers:{...restHeaders,Prefer:'resolution=merge-duplicates,return=minimal'},
          body:JSON.stringify({key:k,value:v})});
        return r.ok;
      }
      if(BACKEND_MODE==='claude'){ return await window.storage.set(k,JSON.stringify(v),true); }
      // local: 持久化到 localStorage
      localStorage.setItem(LS_PREFIX + k, JSON.stringify(v));
      return true;
    }catch(e){ 
      // dup 错误继续向上传播（不被外层 catch 吞掉）
      if(e && e.dup) throw e;
      console.error('set',e); return null; 
    } },
  async del(k){ try{
      if(BACKEND_MODE==='server'){
        const r = await fetch(`${SERVER_URL}/api/data?key=${encodeURIComponent(k)}`, {method:'DELETE'});
        const d = await r.json();
        return d && d.ok;
      }
      if(BACKEND_MODE==='feishu'){ const d=await fx('del',{key:k}); return d&&d.ok; }
      if(BACKEND_MODE==='rest'){ const r=await fetch(`${B.url}/rest/v1/board_kv?key=eq.${encodeURIComponent(k)}`,{method:'DELETE',headers:restHeaders}); return r.ok; }
      if(BACKEND_MODE==='claude'){ return await window.storage.delete(k,true); }
      localStorage.removeItem(LS_PREFIX + k);
      return true;
    }catch(e){ return null; } },
  async list(prefix){ try{
      if(BACKEND_MODE==='server'){
        let keys = [];
        try{
          const r = await fetch(`${SERVER_URL}/api/list?prefix=${encodeURIComponent(prefix||'')}`);
          if(r.ok){ const d = await r.json(); keys = d.keys || []; }
        }catch(e){}
        // 合并本地兜底的 key
        for(let i=0; i<localStorage.length; i++){
          const k = localStorage.key(i);
          if(k && k.startsWith(LS_FALLBACK_PREFIX)){
            const realKey = k.slice(LS_FALLBACK_PREFIX.length);
            if(realKey.startsWith(prefix||'') && !keys.includes(realKey)) keys.push(realKey);
          }
        }
        return keys;
      }
      if(BACKEND_MODE==='feishu'){ const d=await fx('list',{prefix}); return d.keys||[]; }
      if(BACKEND_MODE==='rest'){
        const r=await fetch(`${B.url}/rest/v1/board_kv?key=like.${encodeURIComponent(prefix+'*')}&select=key`,{headers:restHeaders});
        if(!r.ok) throw 0; const a=await r.json(); return a.map(x=>x.key);
      }
      if(BACKEND_MODE==='claude'){ const r=await window.storage.list(prefix,true); return r?r.keys:[]; }
      // local: 扫描 localStorage
      const keys = [];
      for(let i = 0; i < localStorage.length; i++){
        const k = localStorage.key(i);
        if(k && k.startsWith(LS_PREFIX)){
          const realKey = k.slice(LS_PREFIX.length);
          if(realKey.startsWith(prefix)) keys.push(realKey);
        }
      }
      return keys;
    }catch(e){ return []; } }
};

/* 统一接口：shared=true→共享库；false→本设备身份。其余业务代码无需改动 */
const S = {
  get:(k,shared)=> shared ? SHARED.get(k) : PERSONAL.get(k),
  set:(k,v,shared)=> shared ? SHARED.set(k,v) : PERSONAL.set(k,v),
  del:(k,shared)=> shared ? SHARED.del(k) : PERSONAL.del(k),
  list:(prefix,shared)=> shared ? SHARED.list(prefix) : Promise.resolve([])
};
// 追加进共享数组键，按 id 合并以降低并发覆盖
async function appendById(key, item){
  let arr = (await S.get(key,true)) || [];
  const i = arr.findIndex(x=>x.id===item.id);
  if(i>=0) arr[i]=item; else arr.push(item);
  await S.set(key, arr, true);
  return arr;
}
async function removeById(key, id){
  let arr = (await S.get(key,true)) || [];
  arr = arr.filter(x=>x.id!==id);
  await S.set(key, arr, true);
  return arr;
}

/* ============ helpers ============ */
const $=s=>document.querySelector(s);
const AVATARS=['🦈','🐺','🦅','🐯','🦁','🐉','🐆','🦂','⚡','🔥','🚀','🎯','⚔️','🛡️','👑','💎'];
function todayStr(d){ d=d||new Date(); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
function dayOfYear(d){ const s=new Date(d.getFullYear(),0,0); return Math.floor((d-s)/86400000); }
function daysInYear(y){ return ((y%4===0&&y%100!==0)||y%400===0)?366:365; }
// 年度牵引目标 = 从「作战起始日」到当年 12/31（含首尾）的天数，一天一个
function campaignGoal(){
  const ty=new Date(config.target).getFullYear()||2026;
  const start=new Date((config.start||'2026-07-13')+'T00:00:00');
  const end=new Date(ty,11,31,0,0,0);
  const days=Math.round((end-start)/86400000)+1;
  return Math.max(1,days);
}
function typeTag(t){ return t==='吸引伙伴'?'partner':t==='牵引客户'?'customer':'both'; }
function esc(s){ return (s||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
function toast(msg){ const t=$('#toast'); t.textContent=msg; t.classList.add('show'); setTimeout(()=>t.classList.remove('show'),2200); }

