/* ============ 连接状态栏（server 模式实时探活，30s 一次）============ */
function updateConnBar(){
  const cb=$('#connBar'); if(!cb) return;
  if(BACKEND_MODE==='server'){
    if(serverOnline){
      cb.className='connbar ok'; cb.textContent='🟢 已连接团队服务器 · 数据持久化 · 全员实时同步';
    }else{
      // 检查是否有未同步的本地兜底数据
      let pending=0;
      for(let i=0;i<localStorage.length;i++){
        if(localStorage.key(i).startsWith(LS_FALLBACK_PREFIX)) pending++;
      }
      cb.className='connbar warn';
      cb.textContent = pending
        ? '🟡 服务器离线 · '+pending+' 条打卡已暂存本地，恢复后自动同步'
        : '🟡 服务器离线 · 数据暂存本地，恢复后自动同步';
    }
  }else if(BACKEND_MODE==='feishu'){ cb.className='connbar ok'; cb.textContent='🟢 已连接飞书多维表格 · 全员实时同步'; }
  else if(BACKEND_MODE==='rest'){ cb.className='connbar ok'; cb.textContent='🟢 已连接团队共享数据库 · 全员实时同步'; }
  else if(BACKEND_MODE==='claude'){ cb.className='connbar info'; cb.textContent='🔵 预览模式 · 数据在此预览内共享（部署后可全员同步）'; }
  else { cb.className='connbar info'; cb.textContent='💻 本机模式（localStorage）· 单人使用'; }
}

// 启动探活：初始探测 + 30s 轮询 + 同步本地兜底
if(BACKEND_MODE==='server'){
  checkServerHealth().then(()=>{ if(serverOnline) syncFallbackData(); });
  // config 单独 10s 拉一次（权限/队伍变更可立即生效）
  setInterval(async ()=>{
    if(!document.hidden){
      const fresh=await S.get('config',true);
      if(fresh && JSON.stringify(fresh)!==JSON.stringify(config)){
        config={...config,...fresh};
        applyConfig();
        updateSettingsBtn();  // 重新评估按钮显示
        if(me && me.name!==config.superAdmin && me.name==='admin'){
          toast('你的超管权限已变更');
        }
      }
    }
  }, 10000);
  setInterval(async ()=>{
    await checkServerHealth();
    if(serverOnline) await syncFallbackData();
    if(!document.hidden) await refreshShared();
  }, 30000);
  document.addEventListener('visibilitychange', async ()=>{
    if(!document.hidden){
      await checkServerHealth();
      if(serverOnline) await syncFallbackData();
    }
  });
}
// 拉取共享库最新数据并重渲染（供多人同步用）
let refreshing=false;
async function refreshShared(){
  if(refreshing) return; refreshing=true;
  try{
    const cnt=await S.get('counts',true); if(cnt) counts={...counts,...cnt};
    await loadRoster();
    await loadDay(todayStr());
    if(curFilterDate && curFilterDate!==todayStr()) await loadDay(curFilterDate);
    await renderAll();
  }catch(e){}
  refreshing=false;
}

async function loadRoster(){
  const keys=await S.list('roster:',true);
  const out=[];
  for(const k of keys){ const v=await S.get(k,true); if(v) out.push(v); }
  roster=out.sort((a,b)=>(a.ts||0)-(b.ts||0));
}
async function loadDay(ds){
  const arr=(await S.get('day:'+ds,true))||[];
  dayCache[ds]=arr.sort((a,b)=>b.ts-a.ts);
  return dayCache[ds];
}

