function logout(){
  if(me && !confirm('确定要退出当前登录吗？')) return;
  me=null; S.del('me',false);
  openLogin();
  toast('已退出，可切换其他成员登录');
}
async function doLogin(){
  const name=$('#loginName').value.trim();
  if(!name){ $('#loginErr').classList.add('show'); return; }
  $('#loginErr').classList.remove('show');

  // 检查花名册（超管始终允许；其他用户需在花名册中）
  const rosterKeys=await S.list('roster:',true);
  let exists=rosterKeys.some(k=>k.replace('roster:','')===name) || name===config.superAdmin;

  // 兜底：如果 list 没找到，直接尝试读单个 roster key
  if(!exists){
    try{
      const r=await S.get('roster:'+name,true);
      if(r && r.name===name) exists=true;
    }catch(e){}
  }

  if(!exists){
    $('#loginErr').textContent='该名称未注册，请联系管理员进行注册';
    $('#loginErr').classList.add('show');
    return;
  }

  me={name,avatar:pickAvatar};
  await S.set('me',me,false);
  // 确保超管在花名册中（用最新的 rosterKeys）
  if(isSuperAdmin() && !rosterKeys.some(k=>k.replace('roster:','')===name)){
    await S.set('roster:'+name,{name,ts:Date.now()},true);
    await loadRoster();
  }
  showMe(); $('#loginOverlay').classList.remove('on'); closeLogin();
  await renderAll();
  if(isSuperAdmin()){
    toast('超级管理员 '+name+' 已进入战场 ⚔️');
  }else{
    toast(name+' 已进入战场 ⚔️');
  }
  // 登录后执行待定操作
  if(pendingAction){ const fn=pendingAction; pendingAction=null; setTimeout(fn,100); }
}

/* ============ check-in ============ */
let ciType='',ciStatus='';
function openCheckin(preset,lock){
  if(!me){ pendingAction=()=>openCheckin(preset,lock); openLogin(); return; }
  ciType=preset||''; ciStatus='';
  // lock: only show the single allowed type (from a task card); otherwise show all three
  $('#segType').querySelectorAll('button').forEach(b=>{
    const match=b.dataset.v===ciType;
    b.style.display=(lock&&!match)?'none':'';
    b.classList.toggle('sel',match);
  });
  $('#chipsStatus').querySelectorAll('button').forEach(b=>b.classList.remove('sel'));
  $('#ciResult').value=''; $('#ciNext').value=''; $('#ciErr').classList.remove('show');
  $('#checkinOverlay').classList.add('on'); setTimeout(()=>$('#ciResult').focus(),200);
}
let ciSubmitting=false;
async function submitCheckin(){
  // 按钮防抖：避免重复提交
  if(ciSubmitting) return;
  const result=$('#ciResult').value.trim();
  if(!ciType||!result){ $('#ciErr').classList.add('show'); return; }
  ciSubmitting=true;
  const submitBtn=$('#ciSubmit');
  submitBtn.disabled=true;
  submitBtn.textContent='提交中...';
  const ds=todayStr();
  const item={ id:'ck_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),
    name:me.name, avatar:me.avatar, date:ds, type:ciType, result,
    status:ciStatus, next:$('#ciNext').value.trim(), ts:Date.now() };

  // server 模式：使用 /api/checkin 一站式原子提交（不再手动维护 day/member/counts）
  if(BACKEND_MODE==='server' && SERVER_URL){
    try{
      const token=getStoredToken();
      const r=await fetch(SERVER_URL.replace(/\/+$/,'')+'/api/checkin', {
        method:'POST',
        headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},
        body:JSON.stringify({item})
      });
      const d=await r.json();
      if(d && d.ok){
        feishuLogRow(item);
        $('#checkinOverlay').classList.remove('on');
        await refreshShared();  // 从服务端重新拉取全部数据
        toast('战果已提交 🦈 全组都看到了');
      }else if(d && d.dup){
        toast('⚠️ 该打卡记录已存在，请勿重复提交');
      }else{
        toast('提交失败：'+(d.error||'未知错误'));
      }
    }catch(e){
      toast('网络错误，请检查连接后重试');
    }
  }else{
    // 非 server 模式：保留原有逻辑
    try{
      dayCache[ds]=(await appendById('day:'+ds,item)).sort((a,b)=>b.ts-a.ts);
    }catch(e){
      if(e && e.dup){
        toast('⚠️ 该打卡记录已存在，请勿重复提交');
        releaseSubmitBtn();
        return;
      }
      throw e;
    }
    await appendById('member:'+me.name,item);
    if(ciType==='牵引客户'||ciType==='两者都有') counts.customers++;
    if(ciType==='吸引伙伴'||ciType==='两者都有') counts.partners++;
    await S.set('counts',counts,true);
    feishuLogRow(item);
    $('#checkinOverlay').classList.remove('on');
    await renderAll();
    toast('战果已提交 🦈');
  }
  releaseSubmitBtn();
}
function releaseSubmitBtn(){
  ciSubmitting=false;
  var btn=$('#ciSubmit');
  if(btn){ btn.disabled=false; btn.textContent='🦈 提交今日战果'; }
}
async function delCheckin(id,date){
  if(!confirm('删除我的这条打卡记录？')) return;
  // capture the row (for its type) BEFORE deleting so counts roll back correctly
  const src=(dayCache[date]||await loadDay(date));
  const row=src.find(c=>c.id===id);
  const arr=await removeById('day:'+date,id);
  dayCache[date]=arr.sort((a,b)=>b.ts-a.ts);
  await removeById('member:'+me.name,id);
  feishuDelRow(id);     // 飞书可读台账：移除对应行（best-effort）
  if(row){
    if(row.type==='牵引客户'||row.type==='两者都有') counts.customers=Math.max(0,counts.customers-1);
    if(row.type==='吸引伙伴'||row.type==='两者都有') counts.partners=Math.max(0,counts.partners-1);
    await S.set('counts',counts,true);
  }
  await renderAll();
  toast('已删除');
}

/* ============ 大客户牵引方法 · 内嵌文档 ============ */
let docLoaded=false;
function openDoc(){
  const ov=$('#docOverlay'), fr=$('#docFrame');
  if(!ov||!fr) return;
  if(!docLoaded){
    try{
      const b64=(window.BIGCLIENT_DOC_B64||'').replace(/\s+/g,'');
      const html=new TextDecoder('utf-8').decode(Uint8Array.from(atob(b64), c=>c.charCodeAt(0)));
      fr.srcdoc=html;
    }catch(e){ fr.srcdoc='<div style="color:#fff;font-family:sans-serif;padding:24px">文档加载失败，请重试。</div>'; }
    docLoaded=true;
  }
  ov.classList.add('on');
  document.body.style.overflow='hidden';
}
function closeDoc(){ const ov=$('#docOverlay'); if(ov) ov.classList.remove('on'); document.body.style.overflow=''; }

