function updateGoalPreview(){
  const ty=new Date($('#sDate').value||config.target).getFullYear()||2026;
  const start=new Date(($('#sStart').value||config.start)+'T00:00:00');
  const end=new Date(ty,11,31,0,0,0);
  const days=Math.max(1,Math.round((end-start)/86400000)+1);
  $('#sGoalPreview').textContent=days;
}

/* ============ 一键导出 Excel（4 Sheet：打卡明细/每日汇总/团队配置/成员花名册）============ */
async function exportCSV(){
  if(!me){ pendingAction=exportCSV; openLogin(); return; }
  try{
    toast('正在生成报表…');
    const base=SERVER_URL.replace(/\/+$/,'');
    // 优先 Token 鉴权，无 Token 时回退密码参数（向后兼容）
    const token=getStoredToken();
    var url=base+'/api/export-excel';
    var opts={};
    if(token){
      opts.headers={'Authorization':'Bearer '+token};
    }else{
      url+='?password='+encodeURIComponent(PW);
    }
    const resp=await fetch(url, opts);
    if(!resp.ok) throw new Error('export failed');
    const blob=await resp.blob();
    const a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download='作战打卡数据_'+todayStr()+'.xlsx';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),1500);
    toast('已导出 4 Sheet Excel 报表');
  }catch(e){ console.error(e); toast('导出失败，请重试'); }
}

